export * as Slider from './slider.tsx';
export type {
  MarksOwnProps as SliderMarksOwnProps,
  MarksProps as SliderMarksProps,
  RootOwnProps as SliderRootOwnProps,
  RootProps as SliderRootProps,
  ThumbOwnProps as SliderThumbOwnProps,
  ThumbProps as SliderThumbProps,
} from './slider.tsx';

@layer hj.components {
  /* Customise: --hj-slider-track · --hj-slider-thumb · --hj-slider-length (vertical) */
  .hj-slider {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: baseline;
    column-gap: calc(12px * var(--hj-density));
    width: 100%;
    font-family: var(--hj-font-sans);
  }
  .hj-slider[data-orientation='vertical'] {
    display: inline-flex;
    flex-direction: column-reverse;
    align-items: center;
    gap: calc(8px * var(--hj-density));
    width: auto;
  }
  .hj-slider[data-disabled] {
    opacity: 0.4;
  }
  .hj-slider-label {
    font-size: 15px;
    font-weight: 500;
    line-height: 20px;
    color: var(--hj-fg);
  }
  .hj-slider-value {
    font: var(--hj-type-mono);
    letter-spacing: var(--hj-tracking-mono);
    font-variant-numeric: tabular-nums;
    color: var(--hj-fg-dim);
    text-align: end;
  }

  .hj-slider-control {
    grid-column: 1 / -1;
    position: relative;
    display: flex;
    align-items: center;
    height: var(--hj-touch);
    touch-action: none;
    user-select: none;
    cursor: pointer;
  }
  .hj-slider-control[data-orientation='vertical'] {
    width: var(--hj-touch);
    height: var(--hj-slider-length, calc(168px * var(--hj-density-size)));
    justify-content: center;
  }
  .hj-slider-control[data-disabled] {
    cursor: not-allowed;
  }

  /* hanji: 4px track at accent 24%, fill at full accent. */
  .hj-slider-track {
    position: relative;
    width: 100%;
    height: var(--hj-slider-track, 4px);
    border-radius: var(--hj-radius-pill);
    background: color-mix(in srgb, var(--hj-accent) 24%, transparent);
  }
  .hj-slider-track[data-orientation='vertical'] {
    width: var(--hj-slider-track, 4px);
    height: 100%;
  }
  .hj-slider-indicator {
    border-radius: inherit;
    corner-shape: inherit;
    background: var(--hj-accent);
  }
  /* pending-hold: committed here, not yet agreed there */
  .hj-slider[data-pending] .hj-slider-indicator {
    opacity: 0.55;
    transition: opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-slider[data-pending] .hj-slider-thumb::after {
    background: var(--hj-bg);
    box-shadow: inset 0 0 0 2px var(--hj-accent);
  }
  .hj-slider[data-disabled] .hj-slider-indicator {
    background: var(--hj-fg-mute);
  }

  /* The 24px box is the hit area; the 12px dot is drawn by ::after. */
  .hj-slider-thumb {
    width: 24px;
    height: 24px;
    border-radius: 50%;
    outline: none;
    cursor: grab;
    -webkit-tap-highlight-color: transparent;
  }
  .hj-slider-thumb[data-dragging] {
    cursor: grabbing;
  }
  .hj-slider-thumb::after {
    content: '';
    position: absolute;
    inset: 0;
    margin: auto;
    width: var(--hj-slider-thumb, 12px);
    height: var(--hj-slider-thumb, 12px);
    border-radius: 50%;
    background: var(--hj-accent);
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      box-shadow var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-slider[data-disabled] .hj-slider-thumb::after {
    background: var(--hj-fg-mute);
  }
  /* Only the thumb being dragged grows — the focused one, in a range. */
  .hj-slider-thumb:hover::after {
    transform: scale(1.25);
  }
  .hj-slider-thumb[data-dragging]:has(:focus)::after,
  .hj-slider-thumb:active::after {
    transform: scale(1.6);
  }
  .hj-slider-thumb:has(:focus-visible)::after {
    box-shadow:
      0 0 0 3px var(--hj-bg),
      0 0 0 5px var(--hj-focus);
  }

  .hj-slider-bubble {
    position: absolute;
    left: 50%;
    bottom: calc(100% + 4px);
    padding: calc(4px * var(--hj-density)) calc(8px * var(--hj-density));
    border-radius: var(--hj-radius-pill);
    background: var(--hj-fg);
    color: var(--hj-bg);
    font: var(--hj-type-mono);
    letter-spacing: var(--hj-tracking-mono);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    pointer-events: none;
    opacity: 0;
    transform: translateX(-50%) translateY(calc(4px * var(--hj-travel))) scale(0.9);
    transform-origin: 50% 100%;
    transition:
      opacity var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-slider-thumb[data-dragging]:has(:focus) .hj-slider-bubble,
  .hj-slider-thumb:active .hj-slider-bubble,
  .hj-slider-thumb:has(:focus-visible) .hj-slider-bubble {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
    transition:
      opacity var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }
  .hj-slider-thumb[data-orientation='vertical'] .hj-slider-bubble {
    left: calc(100% + 6px);
    bottom: auto;
    top: 50%;
    transform: translateY(-50%) translateX(calc(-4px * var(--hj-travel))) scale(0.9);
    transform-origin: 0 50%;
  }
  .hj-slider-thumb[data-orientation='vertical'][data-dragging]:has(:focus) .hj-slider-bubble,
  .hj-slider-thumb[data-orientation='vertical']:active .hj-slider-bubble,
  .hj-slider-thumb[data-orientation='vertical']:has(:focus-visible) .hj-slider-bubble {
    transform: translateY(-50%) translateX(0) scale(1);
  }

  .hj-slider-marks {
    grid-column: 1 / -1;
    height: 24px;
    margin-top: calc(-12px * var(--hj-density));
    pointer-events: none;
    overflow: visible;
  }
  .hj-slider-marks-svg {
    display: block;
    overflow: visible;
  }
  .hj-slider-mark {
    stroke: color-mix(in srgb, var(--hj-fg) 22%, transparent);
    stroke-width: 2;
    stroke-linecap: round;
  }
  .hj-slider-mark-label {
    fill: var(--hj-fg-mute);
    font: 500 11px var(--hj-font-mono);
  }
}

'use client';
import { Slider as Base } from '@base-ui/react/slider';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

export const Label: HanjiPart<typeof Base.Label> = part(
  Base.Label,
  'Slider.Label',
  'hj-slider-label',
);
export const Value: HanjiPart<typeof Base.Value> = part(
  Base.Value,
  'Slider.Value',
  'hj-slider-value',
);
export const Control: HanjiPart<typeof Base.Control> = part(
  Base.Control,
  'Slider.Control',
  'hj-slider-control',
);
export const Track: HanjiPart<typeof Base.Track> = part(
  Base.Track,
  'Slider.Track',
  'hj-slider-track',
);
export const Indicator: HanjiPart<typeof Base.Indicator> = part(
  Base.Indicator,
  'Slider.Indicator',
  'hj-slider-indicator',
);

/** Base UI's render-function form for the thumb. */
type ThumbRender = Extract<NonNullable<Base.Thumb.Props['render']>, (...args: never[]) => unknown>;

export interface ThumbOwnProps {
  /** Show the value above the thumb while it is dragged or keyboard-focused. @default true */
  bubble?: boolean;
  /** Text for the bubble. Defaults to the number in the runtime locale. */
  formatValue?: (value: number) => string;
}
export interface ThumbProps extends ThumbOwnProps, Base.Thumb.Props {}

/**
 * The 12px thumb, grown to ×1.6 while it is the one being dragged. Its 24px box is the hit
 * area; the value bubble rides above it. (Pass `render` yourself and the bubble is skipped.)
 */
export function Thumb(props: ThumbProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    bubble = true,
    formatValue,
    className,
    render,
    index,
    ...rest
  } = withDefaults(config, 'Slider.Thumb', props);
  const styled = !config.unstyled;
  const renderBubble: ThumbRender = (p, state) => {
    const v = state.values[index ?? 0] ?? state.values[0] ?? 0;
    return (
      <div {...p}>
        {p.children}
        <span className={styled ? 'hj-slider-bubble' : undefined} aria-hidden="true">
          {formatValue ? formatValue(v) : v.toLocaleString()}
        </span>
      </div>
    );
  };
  return (
    <Base.Thumb
      {...rest}
      index={index}
      render={render ?? (bubble ? renderBubble : undefined)}
      className={cls(config, 'Slider.Thumb', 'hj-slider-thumb', className)}
    />
  );
}

export interface MarksOwnProps {
  /** Positions to tick, in the slider's units. */
  values: readonly number[];
  /** Same min/max as the Root. @default 0 / 100 */
  min?: number;
  max?: number;
  /** Optional labels under the ticks (same length as values). */
  labels?: readonly React.ReactNode[];
}
export interface MarksProps extends MarksOwnProps, Omit<React.ComponentProps<'div'>, 'children'> {}

/** Static ticks (and labels) along the track — snap points, defaults, a "recommended" value. */
export function Marks(props: MarksProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    values,
    min = 0,
    max = 100,
    labels,
    className,
    ...rest
  } = withDefaults(config, 'Slider.Marks', props);
  const styled = !config.unstyled;
  const span = max - min || 1;
  // SVG takes percentages as attributes: no per-render style objects.
  return (
    <div
      {...rest}
      aria-hidden="true"
      className={cls(config, 'Slider.Marks', 'hj-slider-marks', className) as string | undefined}
    >
      <svg
        width="100%"
        height="100%"
        className={styled ? 'hj-slider-marks-svg' : undefined}
        focusable="false"
      >
        {values.map((v, i) => {
          const x = `${((v - min) / span) * 100}%`;
          return (
            <g key={v}>
              <line x1={x} x2={x} y1="0" y2="6" className={styled ? 'hj-slider-mark' : undefined} />
              {labels?.[i] !== undefined ? (
                <text
                  x={x}
                  y="20"
                  textAnchor="middle"
                  className={styled ? 'hj-slider-mark-label' : undefined}
                >
                  {labels[i]}
                </text>
              ) : null}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

export interface RootOwnProps {
  /** md: 44px hit row, 4px track (hanji). */
  size?: 'md';
  /**
   * The value lives elsewhere (a speaker, a server) and hasn't agreed yet: the thumb draws hollow
   * and the fill dims until you clear it. hanji's pending-hold.
   */
  pending?: boolean;
}
export interface RootProps extends RootOwnProps, Base.Root.Props {}

/**
 * A value on a continuous scale where the feel matters more than the exact number. Tap to jump,
 * drag to fine-tune, arrows to nudge. Childless, it renders Control › Track › Indicator + Thumb(s)
 * for each value in `value`/`defaultValue`.
 */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    size = 'md',
    pending = false,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Slider.Root', props);
  const initial = rest.value ?? rest.defaultValue;
  const count = Array.isArray(initial) ? initial.length : 1;
  return (
    <Base.Root
      {...rest}
      data-size={size}
      data-pending={flag(pending)}
      aria-busy={pending || undefined}
      className={cls(config, 'Slider.Root', 'hj-slider', className)}
    >
      {children ?? (
        <Control>
          <Track>
            <Indicator />
            {Array.from({ length: count }, (_, i) => (
              <Thumb key={i} index={count > 1 ? i : undefined} />
            ))}
          </Track>
        </Control>
      )}
    </Base.Root>
  );
}
